    C = len(grid[0])
    output = [row[:] for row in grid]

    zeros = [(r, c) for r in range(R) for c in range(C) if grid[r][c] == 0]

    for r, c in zeros:
        v = None
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] != 0:
                v = grid[nr][nc]
                break

        if v is not None:
            rs = [i for i in range(R) for j in range(C) if grid[i][j] == v]
            cs = [j for i in range(R) for j in range(C) if grid[i][j] == v]

            if not rs or not cs:
                continue

            min_r = min(min(rs), r)
            max_r = max(max(rs), r)
            min_c = min(min(cs), c)
            max_c = max(max(cs), c)

            width = max_c - min_c
            height = max_r - min_r

            if width > height:
                for i in range(min_r, max_r + 1):
                    output[i][c] = 0
            else:
                for j in range(min_c, max_c + 1):
                    output[r][j] = 0

    return output
